export const PACKS_BY_ID: Record<string, Pack> = Object.fromEntries(PACKS.map((p) => [p.id, p]));

export const CARDS_BY_ID: Record<string, Card> = Object.fromEntries(ALL_CARDS.map((c) => [c.id, c]));

/** Every card in a pack, in spreadsheet order. */
export function getCardsForPack(packId: string): Card[] {
  return (PACKS_BY_ID[packId]?.cardIds ?? []).map((id) => CARDS_BY_ID[id]);
}
